//! Git 版本管理服务: 基于 `git2` 提供面向普通用户的简化 git 能力。
//!
//! 所有命令以项目根目录为仓库根, 路径一律使用仓库相对路径 (正斜杠分隔)。
//! 操作在后台线程执行, 避免阻塞 Tauri IPC。

use std::{collections::HashMap, path::Path, sync::Once};

use git2::{
    build::CheckoutBuilder, Commit, Delta, Diff, DiffDelta, DiffLine, DiffOptions, Index, Oid,
    Repository, Signature, Status, StatusOptions, Tree,
};
use serde::Serialize;

/// 在后台线程执行阻塞的 git 操作
async fn blocking<T, F>(f: F) -> Result<T, String>
where
    T: Send + 'static,
    F: FnOnce() -> Result<T, String> + Send + 'static,
{
    tauri::async_runtime::spawn_blocking(f)
        .await
        .map_err(|e| e.to_string())?
}

/// 关闭 libgit2 的仓库所有权校验 (全局一次性).
///
/// 该校验 (CVE-2022-24765) 在 Windows 上对部分路径 (如非 ASCII 路径) 会误报
/// "repository path ... is not owned by current user". 编辑器仅操作用户本地打开的
/// 项目, 不涉及不可信远程仓库, 可安全关闭.
static DISABLE_OWNER_CHECK: Once = Once::new();

fn ensure_owner_check_disabled() {
    DISABLE_OWNER_CHECK.call_once(|| unsafe {
        let _ = git2::opts::set_verify_owner_validation(false);
    });
}

