// -------- 工具函数 --------

fn open_repo(path: &str) -> Result<Repository, String> {
    ensure_owner_check_disabled();
    Repository::open(Path::new(path)).map_err(|e| e.to_string())
}

fn head_tree(repo: &Repository) -> Option<Tree<'_>> {
    repo.head().ok()?.peel_to_tree().ok()
}

/// 从树读取某路径的 blob 内容
fn tree_blob(repo: &Repository, tree: &Tree<'_>, path: &str) -> Option<Vec<u8>> {
    let entry = tree.get_path(Path::new(path)).ok()?;
    let object = entry.to_object(repo).ok()?;
    Some(object.peel_to_blob().ok()?.content().to_vec())
}

/// 从索引读取某路径的 blob 内容
fn index_blob(repo: &Repository, index: &Index, path: &str) -> Option<Vec<u8>> {
    let entry = index.get_path(Path::new(path), 0)?;
    let object = repo.find_object(entry.id, None).ok()?;
    Some(object.peel_to_blob().ok()?.content().to_vec())
}

fn is_binary(bytes: &[u8]) -> bool {
    bytes.contains(&0)
}

/// 统计每个文件的新增 / 删除行数
fn per_file_stats(diff: &Diff<'_>) -> HashMap<String, (u64, u64)> {
    let mut map: HashMap<String, (u64, u64)> = HashMap::new();
    let _ = diff.foreach(
        &mut |_delta: DiffDelta<'_>, _progress: f32| true,
        None,
        None,
        Some(
            &mut |delta: DiffDelta<'_>, _hunk: Option<git2::DiffHunk<'_>>, line: DiffLine<'_>| {
                let path = delta.new_file().path().or_else(|| delta.old_file().path());
                if let Some(path) = path {
                    let entry = map.entry(path.to_string_lossy().into_owned()).or_default();
                    match line.origin() {
                        '+' => entry.0 += 1,
                        '-' => entry.1 += 1,
                        _ => {}
                    }
                }
                true
            },
        ),
    );
    map
}

/// 从状态位提取索引(暂存)侧类型
fn index_letter(status: Status) -> Option<char> {
    if status.intersects(Status::INDEX_DELETED) {
        Some('D')
    } else if status.intersects(Status::INDEX_RENAMED) {
        Some('R')
    } else if status.intersects(Status::INDEX_NEW) {
        Some('A')
    } else if status.intersects(Status::INDEX_TYPECHANGE) {
        Some('T')
    } else if status.intersects(Status::INDEX_MODIFIED) {
        Some('M')
    } else {
        None
    }
}

/// 从状态位提取工作区(未暂存)侧类型
fn worktree_letter(status: Status) -> Option<char> {
    if status.intersects(Status::WT_DELETED) {
        Some('D')
    } else if status.intersects(Status::WT_RENAMED) {
        Some('R')
    } else if status.intersects(Status::WT_NEW) {
        Some('U')
    } else if status.intersects(Status::WT_TYPECHANGE) {
        Some('T')
    } else if status.intersects(Status::WT_MODIFIED) {
        Some('M')
    } else {
        None
    }
}

/// 计算仓库状态 (分支 / 暂存 / 未暂存 / 身份)
fn compute_status(repo: &Repository) -> Result<RepoStatus, String> {
    let mut options = StatusOptions::new();
    options
        .include_untracked(true)
        .recurse_untracked_dirs(true)
        .renames_head_to_index(true)
        .renames_index_to_workdir(true);
    let statuses = repo
        .statuses(Some(&mut options))
        .map_err(|e| e.to_string())?;

    // 暂存 / 未暂存差异 (用于行数统计)
    let index = repo.index().map_err(|e| e.to_string())?;
    let head_tree = head_tree(repo);

    let mut staged_stats = HashMap::new();
    if let Ok(diff) = repo.diff_tree_to_index(head_tree.as_ref(), Some(&index), None) {
        staged_stats = per_file_stats(&diff);
    }

    let mut unstaged_stats = HashMap::new();
    let mut diff_opts = DiffOptions::new();
    diff_opts
        .include_untracked(true)
        .recurse_untracked_dirs(true)
        .include_unmodified(false);
    if let Ok(diff) = repo.diff_index_to_workdir(Some(&index), Some(&mut diff_opts)) {
        unstaged_stats = per_file_stats(&diff);
    }

    let mut staged = Vec::new();
    let mut unstaged = Vec::new();
    for entry in statuses.iter() {
        if let Some(path) = entry.path() {
            if let Some(status) = index_letter(entry.status()) {
                let (additions, deletions) = staged_stats.get(path).copied().unwrap_or((0, 0));
                staged.push(FileStatus {
                    path: path.to_string(),
                    status,
                    additions,
                    deletions,
                });
            }
            if let Some(status) = worktree_letter(entry.status()) {
                let (additions, deletions) = unstaged_stats.get(path).copied().unwrap_or((0, 0));
                unstaged.push(FileStatus {
                    path: path.to_string(),
                    status,
                    additions,
                    deletions,
                });
            }
        }
    }

    let branch = repo
        .head()
        .ok()
        .and_then(|h| h.shorthand().map(str::to_string));

    let identity = repo.config().ok().and_then(|config| {
        let name = config.get_string("user.name").ok()?;
        let email = config.get_string("user.email").ok()?;
        Some(Identity { name, email })
    });

    Ok(RepoStatus {
        initialized: true,
        branch,
        staged,
        unstaged,
        identity,
    })
}

/// 提交身份 (供提交前检查)
fn commit_signature(repo: &Repository) -> Result<Signature<'static>, String> {
    let config = repo.config().map_err(|e| e.to_string())?;
    let name = config
        .get_string("user.name")
        .map_err(|_| "缺少提交作者姓名 (user.name)")?;
    let email = config
        .get_string("user.email")
        .map_err(|_| "缺少提交作者邮箱 (user.email)")?;
    Signature::now(&name, &email).map_err(|e| e.to_string())
}

